changeSet.sql:
ALTER TABLE billing.plum_cards ADD COLUMN IF NOT EXISTS user_in TEXT;

UPDATE billing.plum_cards c
   SET user_in = (SELECT COALESCE(u.pinfl, u.tin) FROM "user"."user" u WHERE u.id = c.user_id)
 WHERE c.user_id IS NOT NULL;

ALTER TABLE billing.plum_cards DROP COLUMN IF EXISTS user_id;
